import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import './command-palette.css';

import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { delegate, signal } from 'kerfjs';

type Command = { id: string; label: string; group: 'Navigation' | 'Actions'; run: () => void };
type DialogElement = HTMLElement & { open: boolean };

export function createCommandPalette(root: HTMLElement, commands: Command[]) {
  const open = signal(false);
  const query = signal('');
  const active = signal(0);
  const recent = signal<string[]>(JSON.parse(localStorage.getItem('recentCommands') || '[]'));
  let invoker: HTMLElement | null = null;

  const matches = () => {
    const normalized = query.value.trim().toLowerCase();
    const found = normalized ? commands.filter((command) => command.label.toLowerCase().includes(normalized)) : recent.value.map((id) => commands.find((command) => command.id === id)).filter((command): command is Command => Boolean(command));
    return found;
  };
  const choose = (command: Command) => {
    command.run();
    recent.value = [command.id, ...recent.value.filter((id) => id !== command.id)].slice(0, 6);
    localStorage.setItem('recentCommands', JSON.stringify(recent.value));
    const dialog = root.querySelector<DialogElement>('wa-dialog');
    if (dialog) dialog.open = false;
  };
  const renderResults = () => {
    const found = matches();
    if (found.length === 0) return <EmptyState title="No commands found" detail="Try a different action or destination." />;
    return <div id="command-results" class="command-results" role="listbox" aria-label="Commands">{(['Navigation', 'Actions'] as const).map((group) => { const grouped = found.filter((command) => command.group === group); return grouped.length ? <section aria-labelledby={`command-group-${group}`}><h3 id={`command-group-${group}`}>{query.value ? group : `Recent ${group}`}</h3>{grouped.map((command) => { const index = found.indexOf(command); return <button id={`command-${command.id}`} type="button" role="option" aria-selected={String(active.value === index)} data-action="run-command" data-command-id={command.id}>{command.label}</button>; })}</section> : null; })}</div>;
  };
  const render = () => <><button type="button" data-action="open-command-palette">Open command palette</button><wa-dialog class="command-palette" without-header aria-labelledby="command-palette-title" open={open.value}><DialogHeader title="Command palette" titleId="command-palette-title" summary="Search destinations and actions." summaryId="command-palette-summary" /><div class="command-palette__body kui-dialog-body kui-section-stack"><label for="command-query">Search commands</label><input id="command-query" type="search" role="combobox" autocomplete="off" aria-controls="command-results" aria-expanded="true" aria-activedescendant={matches()[active.value] ? `command-${matches()[active.value]!.id}` : undefined} value={query.value} />{renderResults()}</div></wa-dialog></>;

  const disposeActions = delegate(root, 'click', '[data-action]', (_event, element) => {
    const dialog = root.querySelector<DialogElement>('wa-dialog');
    if (element.dataset.action === 'open-command-palette' && dialog) { invoker = element; open.value = true; dialog.open = true; queueMicrotask(() => root.querySelector<HTMLInputElement>('#command-query')?.focus()); }
    if (element.dataset.action === 'run-command') { const command = commands.find((candidate) => candidate.id === element.dataset.commandId); if (command) choose(command); }
  });
  const onInput = (event: Event) => { if (event.target instanceof HTMLInputElement && event.target.id === 'command-query') { query.value = event.target.value; active.value = 0; } };
  const onKeydown = (event: KeyboardEvent) => {
    if (!(event.target instanceof HTMLInputElement) || event.target.id !== 'command-query') return;
    const found = matches();
    if (event.key === 'ArrowDown' && found.length) { event.preventDefault(); active.value = (active.value + 1) % found.length; }
    if (event.key === 'ArrowUp' && found.length) { event.preventDefault(); active.value = (active.value - 1 + found.length) % found.length; }
    if (event.key === 'Enter' && found[active.value]) { event.preventDefault(); choose(found[active.value]!); }
  };
  const dialog = root.querySelector<DialogElement>('wa-dialog');
  const afterHide = () => { open.value = false; query.value = ''; active.value = 0; invoker?.focus(); };
  root.addEventListener('input', onInput);
  root.addEventListener('keydown', onKeydown);
  dialog?.addEventListener('wa-hide', afterHide);
  return { render, dispose() { disposeActions(); root.removeEventListener('input', onInput); root.removeEventListener('keydown', onKeydown); dialog?.removeEventListener('wa-hide', afterHide); } };
}

