.command-palette { --spacing: 0; --width: min(42rem, calc(100vw - 2rem)); }
.command-palette__body { max-block-size: min(70dvh, 34rem); overflow: auto; }
.command-palette__body label { font-weight: var(--kui-font-weight-semibold); }
.command-palette__body input { inline-size: 100%; min-block-size: 2.5rem; padding-inline: var(--kui-space-s); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); color: var(--kui-color-text); background: var(--kui-color-surface); }
.command-palette__body input:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
.command-results { display: grid; gap: var(--kui-layout-section-gap); }
.command-results section { display: grid; gap: var(--kui-layout-control-gap); }
.command-results h3 { margin: 0; color: var(--kui-color-text-quiet); font-size: var(--kui-font-xs); }
.command-results button { min-block-size: 2.5rem; padding: var(--kui-space-s); border: 0; border-radius: var(--kui-radius-m); color: var(--kui-color-text); background: transparent; text-align: start; }
.command-results button[aria-selected="true"] { background: var(--kui-color-neutral-fill-normal); }
.command-results button:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
